<?php
require_once __DIR__.'/../configuracion/admin-ui.php';require_once __DIR__.'/../configuracion/autentifica_admin.php';
$courses=neo_courses();$course=(int)app_value($_GET,'curso_seleccionado',neo_current_course($courses));$q=trim(app_value($_GET,'q'));$state=app_value($_GET,'estado');$page=max(1,(int)app_value($_GET,'pagina',1));$size=50;
$where='(c.id_centro=0 OR c.id_centro=?)';$types='i';$args=array((int)$centro_actual);
if($course){$where.=' AND c.id_curso=?';$types.='i';$args[]=$course;}
if($q!==''){$where.=" AND CONCAT_WS(' ',c.Nombre,c.Apellido1,c.Apellido2,c.persona_contacto,c.nombre_padre2,c.telefono,c.email,c.email_padre2) LIKE ?";$types.='s';$args[]='%'.$q.'%';}
if($state!==''){$where.=' AND c.proceso_decision=?';$types.='s';$args[]=$state;}
$total=(int)app_rows('SELECT COUNT(*) AS n FROM contactos c WHERE '.$where,$types,$args)[0]['n'];$page=min($page,max(1,(int)ceil($total/$size)));$offset=($page-1)*$size;
$rows=app_rows('SELECT c.*,ce.nombre_centro,ca.nombre AS curso_nombre,u.Nombre AS alumno_nombre,u.Apellido1 AS alumno_apellido1,u.Apellido2 AS alumno_apellido2 FROM contactos c LEFT JOIN centros ce ON ce.id_centro=c.id_centro LEFT JOIN cursos_academicos ca ON ca.id_curso=c.id_curso LEFT JOIN usuarios u ON u.id_usuario=c.id_usuario WHERE '.$where.' ORDER BY c.fecha_contacto DESC,c.id_contacto DESC LIMIT '.$size.' OFFSET '.$offset,$types,$args);
$states=app_rows('SELECT DISTINCT proceso_decision FROM contactos WHERE id_centro=0 OR id_centro=? ORDER BY proceso_decision','i',array((int)$centro_actual));
neo_page_start('Contactos','Consulta el seguimiento, localiza una familia y abre sus datos sin perder el listado.','Alumnos');
?>
<section class="neo-panel"><form method="get" class="neo-filters"><label class="grow">Buscar contacto<input type="search" name="q" value="<?=app_escape($q)?>" placeholder="Nombre, familiar, teléfono o correo"></label><label>Curso<select name="curso_seleccionado"><option value="0">Todos los cursos</option><?php foreach($courses as $c){ ?><option value="<?=(int)$c['id_curso']?>" <?=((int)$c['id_curso']===$course?'selected':'')?>><?=app_escape($c['nombre'])?></option><?php } ?></select></label><label>Estado<select name="estado"><option value="">Todos los estados</option><?php foreach($states as $s){if($s['proceso_decision']==='')continue; ?><option value="<?=app_escape($s['proceso_decision'])?>" <?=($state===$s['proceso_decision']?'selected':'')?>>Estado <?=app_escape($s['proceso_decision'])?></option><?php } ?></select></label><button>Aplicar filtros</button><a class="neo-button secondary" href="listado_contactos.php">Restablecer</a></form></section>
<div class="neo-heading"><span class="neo-muted"><?=$total?> contactos · Mostrando <?=count($rows)?></span><div class="neo-actions"><a class="neo-button secondary" href="informe_contactos.php?curso=<?=$course?>">Ver informe</a><a class="neo-button" href="nuevo_contacto.php">+ Nuevo contacto</a></div></div>
<div class="neo-table-wrap"><table class="neo-data-table"><thead><tr><th>Contacto</th><th>Seguimiento</th><th>Familia</th><th>Teléfono y correo</th><th>Alumno asociado</th><th>Acciones</th></tr></thead><tbody>
<?php foreach($rows as $r){$name=trim($r['Nombre'].' '.$r['Apellido1'].' '.$r['Apellido2']); ?><tr><td><a href="nuevo_contacto.php?id_contacto=<?=(int)$r['id_contacto']?>"><?=app_escape($name?:'Nombre pendiente')?></a><small>Nacimiento: <?=neo_date($r['fecha_nacimiento'])?></small><small><?=app_escape($r['poblacion'])?></small></td><td><span class="neo-pill">Estado <?=app_escape($r['proceso_decision']?:'pendiente')?></span><small>Contacto: <?=neo_date($r['fecha_contacto'])?></small><small><?=app_escape($r['curso_nombre']?:'Sin curso')?></small><small><?=app_escape($r['nombre_centro']?:'Pendiente de asignar centro')?></small></td><td><strong><?=app_escape($r['persona_contacto']?:'Contacto pendiente')?></strong><?php if($r['nombre_padre2']){ ?><small><?=app_escape($r['nombre_padre2'])?></small><?php } ?><details><summary>Más datos</summary><div class="neo-contact-detail"><p>DNI: <?=app_escape($r['dni_padre1']?:'—')?><?=($r['dni_padre2']?' / '.app_escape($r['dni_padre2']):'')?></p><p><?=app_escape($r['calle'].' '.$r['codigo_postal'].' '.$r['poblacion'])?></p><p><?=nl2br(app_escape($r['comentarios']))?></p></div></details></td><td><div class="neo-contact-detail"><?=app_escape($r['telefono']?:'Sin teléfono')?><small><?=app_escape($r['email']?:'Sin correo')?></small><?php if($r['telefono_padre2']||$r['email_padre2']){ ?><small><?=app_escape($r['telefono_padre2'])?><br><?=app_escape($r['email_padre2'])?></small><?php } ?></div></td><td><?php if($r['id_usuario']&&$r['alumno_nombre']){ ?><a href="/alumnos/nuevo_alumno1.php?u=<?=(int)$r['id_usuario']?>"><?=app_escape(trim($r['alumno_nombre'].' '.$r['alumno_apellido1'].' '.$r['alumno_apellido2']))?></a><?php }else{ ?><span class="neo-muted">Sin vincular</span><?php } ?><small><?php if($r['codigo_uso_unico'])echo 'Formulario pendiente'.($r['fecha_envio_codigo']?' · '.neo_date($r['fecha_envio_codigo']):'');elseif($r['fecha_uso_codigo']&&$r['fecha_uso_codigo']!=='0000-00-00')echo 'Formulario completado · '.neo_date($r['fecha_uso_codigo']); ?></small></td><td><a class="neo-button secondary" href="nuevo_contacto.php?id_contacto=<?=(int)$r['id_contacto']?>">Editar</a><details><summary>Más acciones</summary><div class="neo-actions"><?php if((int)$nivel_acceso===4){ ?><form method="post" action="/mailer/enviar_codigo.php?id_contacto=<?=(int)$r['id_contacto']?>" data-confirm="Se enviará una invitación a esta familia. ¿Continuar?"><input type="hidden" name="_csrf" value="<?=app_csrf_token()?>"><button class="secondary">Enviar invitación</button></form><a class="neo-button secondary" href="/mailer/generar_qr.php?id_contacto=<?=(int)$r['id_contacto']?>" target="_blank" rel="noopener">Código QR</a><?php } ?><form method="post" action="eliminar_contacto.php?id_contacto=<?=(int)$r['id_contacto']?>" data-confirm="¿Eliminar este contacto?"><input type="hidden" name="_csrf" value="<?=app_csrf_token()?>"><button class="danger">Eliminar</button></form></div></details></td></tr><?php } ?>
<?php if(!$rows){ ?><tr><td colspan="6" class="neo-empty">No hay contactos que coincidan con los filtros.</td></tr><?php } ?></tbody></table></div>
<?php neo_pagination($total,$page,$size);neo_page_end();
